import{_ as r,o as t,c as o,a5 as s}from"./chunks/framework.Bt0SrEfo.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"图片上传方案.md","filePath":"图片上传方案.md","lastUpdated":1788613730000}'),l={name:"图片上传方案.md"};function i(n,e,a,c,d,g){return t(),o("div",null,[...e[0]||(e[0]=[s('<p><strong>有的！采用“图床与代码彻底分离”的双仓库策略（GitHub 纯图片仓库 + Vercel 纯 Markdown 博客）。</strong></p><p>这套方案完美解决了你的所有顾虑，具体运作方式如下：</p><h4 id="_1-仓库拆分-彻底隔离负担" tabindex="-1">1. 仓库拆分（彻底隔离负担） <a class="header-anchor" href="#_1-仓库拆分-彻底隔离负担" aria-label="Permalink to &quot;1. 仓库拆分（彻底隔离负担）&quot;">​</a></h4><ul><li><p><strong>仓库 A (<code>my-blog-source</code>)</strong>：只存 Markdown 文件、组件和配置文件。<strong>里面一张图片都没有</strong>，整个仓库干净得像刚初始化的一样，体积只有几兆。</p></li><li><p><strong>仓库 B (<code>my-blog-images</code>)</strong>：<strong>专门用来当免费图床的 GitHub 仓库</strong>。所有的截图、架构图全扔在这里。</p></li></ul><h4 id="_2-工作流是怎么样的" tabindex="-1">2. 工作流是怎么样的？ <a class="header-anchor" href="#_2-工作流是怎么样的" aria-label="Permalink to &quot;2. 工作流是怎么样的？&quot;">​</a></h4><ol><li><p><strong>写文章/截图</strong>：你在本地写 Markdown 时，通过 PicGo 快捷键截图上传。PicGo 自动把图片推送到<strong>仓库 B (<code>my-blog-images</code>)</strong>，并返回一串 <code>[https://cdn.jsdelivr.net/](https://cdn.jsdelivr.net/)...</code> 的外链。</p></li><li><p><strong>写进文章</strong>：你在 Markdown 里直接贴这串 CDN 链接：<code>![架构图](https://cdn.jsdelivr.net/gh/你的用户名/my-blog-images/img/20260904.png)</code></p></li><li><p><strong>推送到 Vercel</strong>：你把<strong>仓库 A</strong>（只有纯文本）<code>git push</code> 到 GitHub，Vercel 拉取仓库 A 进行构建。</p><ul><li><p><strong>因为仓库 A 里没有图片</strong>，Vercel 构建速度飞快（几乎秒级完成）。</p></li><li><p><strong>图片不经过 Vercel 服务器</strong>，而是用户在浏览网页时，浏览器直接去请求 jsDelivr CDN。</p></li></ul></li></ol><h3 id="这套-双仓库-jsdelivr-方案的优势" tabindex="-1">这套“双仓库 + jsDelivr”方案的优势： <a class="header-anchor" href="#这套-双仓库-jsdelivr-方案的优势" aria-label="Permalink to &quot;这套“双仓库 + jsDelivr”方案的优势：&quot;">​</a></h3><ul><li><p><strong>零费用</strong>：GitHub 仓库免费，jsDelivr 加速免费，Vercel 托管免费。</p></li><li><p><strong>Git 仓库永远轻量</strong>：你的代码仓库永远只有纯文本，提交、拉取代码都是毫秒级。</p></li><li><p><strong>Vercel 构建极快</strong>：不受图片数量影响，十万张图片也不会拖慢 Vercel 部署。</p></li><li><p><strong>完美的迁移性</strong>：如果有一天你想换博客框架（比如从 VitePress 换成 Docusaurus），或者换托管平台，你的图片链接依然在 jsDelivr 上稳稳活着，一处都不用改。</p></li></ul>',8)])])}const u=r(l,[["render",i]]);export{_ as __pageData,u as default};
